 static NativePlayerVitalCompletions.Receipt reserve(Fixture f){return NativeSourceTargetNegativeReserve.reserve(f.peer(),f.first().c());}
 static void mutate(Fixture f,String mode){var a=f.first();var b=a.base().base();switch(mode){case "normal"->{}case "DRAINING"->put(b.life(),"mode",NativePlayerLifetime.Mode.DRAINING);case "STOPPED"->put(b.life(),"mode",NativePlayerLifetime.Mode.STOPPED);case "Main"->put(b.hub(),"nativeStaticMotionClosed",true);case "lifetime"->put(b.hub(),"sourcePlayerCommitLifetime",null);case "foreign-life"->{try{put(b.hub(),"sourcePlayerCommitLifetime",SourceSignedRecoveryPlan.unsafe().allocateInstance(NativePlayerLifetime.class));}catch(Exception e){throw new AssertionError(e);}}case "owner-role"->put(a.owner(),"selectedCharacter","replaced-owner");case "source-role"->put(b.caster(),"selectedCharacter","replaced-source");case "owner-status"->put(a.owner(),"timedStatus",null);case "source-status"->put(b.caster(),"timedStatus",null);case "owner-life"->CombatAccess.set(CombatAccess.field(CombatAccess.field(a.owner(),"timedStatus"),"sourcePoisonLifecycle"),"sourceNpcOwner",new Object());case "pet-status"->put(a.pet(),"timedStatus",null);case "pet-life"->CombatAccess.set(CombatAccess.field(a.timed(),"sourcePoisonLifecycle"),"sourceNpcOwner",new Object());case "attachment"->put(a.owner(),"battleCompanion",null);case "closed-proof"->NativeSourceTargetNegativeLife.close(a.c());case "application"->put(b.life(),"application",null);case "app-closing"->put(f.app(),"closing",true);default->throw new AssertionError(mode);}}
 static void noInit(Fixture f,String mode){var a=f.first();var b=a.base().base();if(mode.equals("lifetime"))check(CombatAccess.field(b.hub(),"sourcePlayerCommitLifetime")==null,"reservation never creates missing lifetime");if(mode.equals("owner-status"))check(CombatAccess.field(a.owner(),"timedStatus")==null,"reservation never creates missing peer status");if(mode.equals("source-status"))check(CombatAccess.field(b.caster(),"timedStatus")==null,"reservation never creates missing source status");if(mode.equals("pet-status"))check(CombatAccess.field(a.pet(),"timedStatus")==null,"reservation never creates missing controlled status");}
 static void release(Fixture f,NativePlayerVitalCompletions.Receipt r,long before){check(r.pc==f.peer()&&r.life==f.first().base().base().life()&&r.app==f.app(),"original Receipt retains exact first peer/life/application");check(NativePlayerVitalCompletions.pending(r.life)==before+1&&(f.app()==null||(int)CombatAccess.field(f.app(),"handlers")==1),"original pending and app handler counters register exactly once");r.close();check(r.released.get()&&NativePlayerVitalCompletions.pending(r.life)==before&&(f.app()==null||(int)CombatAccess.field(f.app(),"handlers")==0),"original close releases pending and app handler exactly once");try{r.close();throw new AssertionError("double close accepted");}catch(IllegalStateException expected){check(NativePlayerVitalCompletions.pending(r.life)==before&&(f.app()==null||(int)CombatAccess.field(f.app(),"handlers")==0),"original double release rejection leaves counters unchanged");}receipts++;}
 static void fence(boolean controlled,String mode,boolean inside)throws Throwable{var f=fixture(controlled,true);var life=f.first().base().base().life();long before=NativePlayerVitalCompletions.pending(life);var result=new AtomicReference<NativePlayerVitalCompletions.Receipt>();var failure=new AtomicReference<Throwable>();var started=new CountDownLatch(1);var worker=new Thread(()->{var stack=NativeServerLifetime.packets.get();if(inside)stack.addLast(f.app());try{started.countDown();result.set(reserve(f));if(inside)check(stack.size()==1&&stack.peekLast()==f.app(),"original app packet scope retained during reservation");}catch(Throwable e){failure.set(e);}finally{if(inside)stack.removeLast();NativeServerLifetime.packets.remove();}},"material-original-peer-receipt-app-fence");synchronized(f.app().fence){worker.start();check(started.await(3,TimeUnit.SECONDS),"peer reservation worker started");SourceElementAudiencePlan.blocked(worker,"actual original application fence "+mode);check(Arrays.stream(worker.getStackTrace()).anyMatch(x->x.getClassName().endsWith("NativePlayerVitalCompletions")&&x.getMethodName().equals("nativeSourceTargetNegativeReserve")),"reservation blocks in complete original native reserve sibling");mutate(f,mode);}worker.join(3000);check(!worker.isAlive()&&failure.get()==null,"original app-fence reservation terminates without leaked monitor");boolean allowed=Set.of("normal","DRAINING").contains(mode)||inside&&mode.equals("app-closing")||!controlled&&Set.of("pet-status","pet-life","attachment").contains(mode);if(allowed){check(result.get()!=null,"current original peer proof is admitted after original fence "+controlled+"/"+mode);release(f,result.get(),before);}else check(result.get()==null&&NativePlayerVitalCompletions.pending(life)==before&&(int)CombatAccess.field(f.app(),"handlers")==0,"stale or closing peer rejected before original Receipt/counters "+controlled+"/"+mode);noInit(f,mode);check(NativeSourceTargetNegativeReserve.class.getDeclaredFields().length==0,"no new global actor registry/TLS/worker");NativeSourceTargetNegativeLife.close(f.first().c());waits++;}
 static void noApplication(boolean controlled,String mode)throws Exception{var f=fixture(controlled,false);long before=NativePlayerVitalCompletions.pending(f.first().base().base().life());mutate(f,mode);var r=reserve(f);boolean allowed=Set.of("normal","DRAINING").contains(mode);if(allowed){check(r!=null,"original no-application processes branch retains first current lifetime "+mode);release(f,r,before);}else check(r==null&&NativePlayerVitalCompletions.pending(f.first().base().base().life())==before,"invalid no-app proof never initializes/registers replacement identity "+mode);noInit(f,mode);NativeSourceTargetNegativeLife.close(f.first().c());}
 static final class FailingMap extends ConcurrentHashMap<NativePlayerLifetime,Long>{final RuntimeException failure=new IllegalStateException("detached-original-Receipt-constructor");@Override public Long compute(NativePlayerLifetime key,BiFunction<? super NativePlayerLifetime,? super Long,? extends Long> f){throw failure;}}
 static void constructorFailure()throws Exception{var f=fixture(true,true);var field=NativePlayerVitalCompletions.class.getDeclaredField("pending");field.setAccessible(true);Object old=field.get(null);var unsafe=SourceSignedRecoveryPlan.unsafe();Object base=unsafe.staticFieldBase(field);long offset=unsafe.staticFieldOffset(field);var failing=new FailingMap();try{unsafe.putObjectVolatile(base,offset,failing);try{reserve(f);throw new AssertionError("constructor failure swallowed");}catch(RuntimeException expected){check(expected==failing.failure&&(int)CombatAccess.field(f.app(),"handlers")==0,"original constructor Throwable handler rolls app counter back and propagates exact failure");}check(!Thread.holdsLock(f.app().fence),"original constructor-failure monitor exit retained");rollbacks++;}finally{unsafe.putObjectVolatile(base,offset,old);NativeSourceTargetNegativeLife.close(f.first().c());}check(NativePlayerVitalCompletions.pending(f.first().base().base().life())==0,"failed constructor has no receipt leak in original pending map");}
 static void originalCaller(int id,long target,String mode)throws Throwable{var f=fixture(true,true);var b=f.first().base().base();for(var pc:List.of(b.caster(),b.target(),b.viewer(),b.observer())){if(CombatAccess.field(pc,"battleCompanion")==null){var unused=SourceNpcFactoryTypePlan.actor(900+pc.playerObjectId(),BattleCompanion.Kind.SUMMON);put(unused,"active",false);put(pc,"battleCompanion",unused);}put(pc,"tamedCompanions",new ArrayList<BattleCompanion>());put(pc,"sourceItemAdmissionGate",new Object());}var field=NativeSkillTargetMetadata.class.getDeclaredField("rows");field.setAccessible(true);Object old=field.get(null);long before=NativePlayerVitalCompletions.pending(b.life());var called=new AtomicInteger();var failure=new AtomicReference<Throwable>();try{field.set(null,Map.of(id,new NativeSkillTargetMetadata.Row("attack",3,10,0,false,1,0,id)));var worker=new Thread(()->{try{NativeControlledNegativeMaterial.cast(b.caster(),SourceTargetNegativeLifePlan.packet(id,target),()->{check(NativeSourceTargetNegativeLife.current(NativeAreaMaterialAction.current.get()),"actual original material callback retains its first proof after peer reservation");called.incrementAndGet();});}catch(Throwable e){failure.set(e);}},"material-original-cast-peer-reserve");synchronized(f.app().fence){worker.start();SourceElementAudiencePlan.blocked(worker,"actual original material caller peer reserve "+mode);check(Arrays.stream(worker.getStackTrace()).anyMatch(x->x.getClassName().endsWith("NativeControlledNegativeMaterial")&&x.getMethodName().equals("cast"))&&Arrays.stream(worker.getStackTrace()).anyMatch(x->x.getMethodName().equals("nativeSourceTargetNegativeReserve")),"actual original cast passes first Context through exact peer reserve caller");mutate(f,mode);}worker.join(3000);check(!worker.isAlive()&&failure.get()==null&&called.get()==(Set.of("normal","DRAINING").contains(mode)?1:0),"actual original material caller rejects stale peer before original callback "+id+"/"+target+"/"+mode);check(NativePlayerVitalCompletions.pending(b.life())==before&&(int)CombatAccess.field(f.app(),"handlers")==0&&!b.caster().nativePlayerActionLock().isLocked()&&!b.target().nativePlayerActionLock().isLocked(),"actual original caller terminal closes counters and releases pair");noInit(f,mode);callerCasts++;}finally{field.set(null,old);NativeSourceTargetNegativeLife.close(f.first().c());}}
 static void fallback()throws Exception{var f=fixture(false,false);var c=f.first().c();long before=NativePlayerVitalCompletions.pending(f.first().base().base().life());check(NativeSourceTargetNegativeReserve.reserve(f.first().base().base().viewer(),c)==null&&NativePlayerVitalCompletions.pending(f.first().base().base().life())==before,"unselected peer cannot borrow original material reserve proof");NativeSourceTargetNegativeLife.close(c);put(c,"phase","WORLD");var r=reserve(f);check(r!=null,"WORLD delegates complete original reserve without a BATTLE proof");release(f,r,before);put(c,"phase","BATTLE");var rules=CombatRules.class.getDeclaredField("current");rules.setAccessible(true);Object old=rules.get(null);try{rules.set(null,null);r=reserve(f);check(r!=null,"unloaded controls delegate original reserve");release(f,r,before);}finally{rules.set(null,old);}}
 public static void main(String[]args)throws Throwable{var rules=CombatRules.class.getDeclaredField("current");rules.setAccessible(true);Object old=rules.get(null);var controls=NativeSourceOtherControls.class.getDeclaredField("current");controls.setAccessible(true);Object oldControls=controls.get(null);var frames=SourceNpcHpOutputPlan.frames();var prior=frames.get();var area=NativeAreaMaterialAction.current;var previous=area.get();try{var path=java.nio.file.Path.of("detached-peer-reserve-no-SQL");rules.set(null,new CombatRules.Snapshot(Map.of(),path,path,path,Set.of(),path));var props=new Properties();props.setProperty("hpbar","true");controls.set(null,new NativeSourceOtherControls.Snapshot(NativeSourceDisplayPlan.Settings.read(props),path));for(boolean controlled:List.of(false,true)){for(String mode:List.of("normal","DRAINING","STOPPED","Main","lifetime","foreign-life","owner-role","source-role","owner-status","source-status","owner-life","pet-status","pet-life","attachment","closed-proof","application","app-closing"))fence(controlled,mode,false);for(String mode:List.of("app-closing","Main","STOPPED","owner-role"))fence(controlled,mode,true);for(String mode:List.of("normal","DRAINING","STOPPED","Main","lifetime","owner-status","closed-proof"))noApplication(controlled,mode);}for(int id:List.of(173,174))for(long target:new long[]{55,777})for(String mode:List.of("normal","DRAINING","Main","STOPPED","lifetime","owner-role","owner-status","app-closing"))originalCaller(id,target,mode);constructorFailure();fallback();check(waits==42&&rollbacks==1,"all original app fence waits and constructor rollback exercised");}finally{NativeServerLifetime.packets.remove();controls.set(null,oldControls);rules.set(null,old);if(prior==null)frames.remove();else frames.set(prior);if(previous==null)area.remove();else area.set(previous);}check(frames.get()==prior&&area.get()==previous,"original Frame and Context TLS restored");System.out.println("PASS"+cases+" target-negative peer reserve actual-original-fence/Receipt/rollback/no-initialization contracts; original-fence-waits="+waits+", original-receipts="+receipts+", constructor-rollbacks="+rollbacks+", original-caller-casts="+callerCasts+"; full material costs/status/IO/other-lifecycles/Main/backend/MySQL/game remain open");}
